CREATE TABLE IF NOT EXISTS demo_actions(id TEXT PRIMARY KEY,actor TEXT NOT NULL,kind TEXT NOT NULL,resource TEXT NOT NULL,created_at TEXT NOT NULL,status TEXT NOT NULL,intent TEXT NOT NULL,data TEXT NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS demo_action_uncertain_resource ON demo_actions(resource) WHERE status IN ('SUBMITTING','PENDING','UNKNOWN','AMEND_PENDING','CANCEL_PENDING');
